$rutaBoletinInicio = static function ($valor): string {
    $ruta = str_replace('\\', '/', trim((string)$valor));

    if (
        !str_starts_with($ruta, 'uploads/')
        || str_contains($ruta, '..')
        || preg_match('/[\x00-\x1F]/', $ruta)
    ) {
        return '';
    }

    return '../' . implode(
        '/',
        array_map('rawurlencode', explode('/', $ruta))
    );
};

